import{_ as t,c as o,o as d,b2 as c}from"./chunks/framework.CUhoHPxN.js";const _=JSON.parse('{"title":"通知公告设计文档","description":"","frontmatter":{},"headers":[],"relativePath":"superpowers/specs/2026-05-14-notice-announcement-design.md","filePath":"superpowers/specs/2026-05-14-notice-announcement-design.md"}'),a={name:"superpowers/specs/2026-05-14-notice-announcement-design.md"};function i(r,e,l,n,s,h){return d(),o("div",null,[...e[0]||(e[0]=[c('<h1 id="通知公告设计文档" tabindex="-1">通知公告设计文档 <a class="header-anchor vp-link" href="#通知公告设计文档" aria-label="Permalink to &quot;通知公告设计文档&quot;">​</a></h1><h2 id="_1-背景与目标" tabindex="-1">1. 背景与目标 <a class="header-anchor vp-link" href="#_1-背景与目标" aria-label="Permalink to &quot;1. 背景与目标&quot;">​</a></h2><p>在系统管理域内提供「通知公告」维护能力：支持按条件查询、分页列表、详情回显、新增、编辑、单条与批量删除；表单支持富文本内容；类型与状态依赖数据字典正确回显。</p><p>原始需求文档见 <code>原始需求/系统管理/通知公告-需求文档.md</code>。本文档为经 <code>/brainstorming</code> 澄清后的<strong>定稿设计</strong>，与需求不一致处以本文为准（尤其 HTTP 方法与列表分页契约）。</p><h2 id="_2-需求澄清结论-已确认" tabindex="-1">2. 需求澄清结论（已确认） <a class="header-anchor vp-link" href="#_2-需求澄清结论-已确认" aria-label="Permalink to &quot;2. 需求澄清结论（已确认）&quot;">​</a></h2><div class="vp-table"><table><thead><tr><th>序号</th><th>结论</th></tr></thead><tbody><tr><td>1</td><td>列表「创建人」与查询「操作人员」统一为<strong>创建人</strong>，查询条件字段为 <code>createBy</code>。</td></tr><tr><td>2</td><td>列表与写操作接口风格对齐仓库约定：读用 <code>GET</code>，<strong>新增/修改/删除统一 <code>POST</code> 子路径</strong>（不使用 <code>PUT</code>/<code>DELETE</code>）。</td></tr><tr><td>3</td><td>公告内容存 <strong>HTML 字符串</strong>；持久化前在服务端做 <strong>白名单 HTML 消毒</strong>；消毒后按 <strong>UTF-8 字符数 ≤ 65535</strong> 校验（与 <code>LONGTEXT</code> 常见用法一致；若驱动或库有更严限制则在实现中下调并注明）。</td></tr><tr><td>4</td><td>字典类型固定为 <strong><code>sys_notice_type</code></strong>、<strong><code>sys_notice_status</code></strong>（与 RuoYi 常用编码一致）。</td></tr><tr><td>5</td><td>界面「公告编号」即主键 <strong><code>noticeId</code></strong>，无独立业务流水号。</td></tr></tbody></table></div><h2 id="_3-范围与非范围" tabindex="-1">3. 范围与非范围 <a class="header-anchor vp-link" href="#_3-范围与非范围" aria-label="Permalink to &quot;3. 范围与非范围&quot;">​</a></h2><h3 id="_3-1-实施范围" tabindex="-1">3.1 实施范围 <a class="header-anchor vp-link" href="#_3-1-实施范围" aria-label="Permalink to &quot;3.1 实施范围&quot;">​</a></h3><ul><li>后端：<code>sys_notice</code> 表、Flyway 迁移、领域模型、Mapper、Service、Controller、入参校验与富文本消毒。</li><li>同批次或衔接迁移中写入 <strong><code>sys_notice_type</code> / <code>sys_notice_status</code></strong> 字典类型及字典项初始数据，保证开箱可验收「字典显示正确」。</li><li>前端：<code>quick-ui</code> 路由、菜单、API 模块、列表页（<code>C7JsonTable</code>）、弹窗表单、富文本编辑器、权限指令。</li><li>权限点与需求一致：<code>system:notice:list</code>、<code>system:notice:add</code>、<code>system:notice:edit</code>、<code>system:notice:remove</code>（与后端鉴权、前端 <code>v-hasPermi</code> 对齐；若项目统一使用 <code>query</code> 替代 <code>list</code>，实现时以全局菜单脚本为准并在此文档勘误）。</li></ul><h3 id="_3-2-明确不做" tabindex="-1">3.2 明确不做 <a class="header-anchor vp-link" href="#_3-2-明确不做" aria-label="Permalink to &quot;3.2 明确不做&quot;">​</a></h3><ul><li>门户/首页滚动公告、站内信、已读未读、推送、评论、版本历史、回收站。</li><li>不做逻辑删除（删除为<strong>物理删除</strong>）。</li><li>不做独立 OSS 存正文（正文随表字段存储）。</li></ul><h2 id="_4-数据模型" tabindex="-1">4. 数据模型 <a class="header-anchor vp-link" href="#_4-数据模型" aria-label="Permalink to &quot;4. 数据模型&quot;">​</a></h2><h3 id="_4-1-表-sys-notice" tabindex="-1">4.1 表 <code>sys_notice</code> <a class="header-anchor vp-link" href="#_4-1-表-sys-notice" aria-label="Permalink to &quot;4.1 表 `sys_notice`&quot;">​</a></h3><div class="vp-table"><table><thead><tr><th>字段</th><th>类型（建议）</th><th>说明</th></tr></thead><tbody><tr><td><code>notice_id</code></td><td>BIGINT PK</td><td>自增或雪花策略与现有 <code>sys_*</code> 表一致</td></tr><tr><td><code>notice_title</code></td><td>VARCHAR(50)</td><td>非空；与常见 RuoYi 模型一致，超长由前后端校验拦截</td></tr><tr><td><code>notice_type</code></td><td>CHAR(1)</td><td>非空；字典 <code>sys_notice_type</code></td></tr><tr><td><code>notice_content</code></td><td>LONGTEXT</td><td>可空；存消毒后 HTML</td></tr><tr><td><code>status</code></td><td>CHAR(1)</td><td>默认 <code>0</code>；字典 <code>sys_notice_status</code>（如 0 正常 / 1 关闭）</td></tr><tr><td><code>create_by</code></td><td>VARCHAR(64)</td><td>创建人</td></tr><tr><td><code>create_time</code></td><td>DATETIME</td><td>创建时间</td></tr><tr><td><code>update_by</code></td><td>VARCHAR(64)</td><td>更新人</td></tr><tr><td><code>update_time</code></td><td>DATETIME</td><td>更新时间</td></tr></tbody></table></div><p>可选：<code>remark</code>（VARCHAR）——若不做可省略以保持最小表。</p><p>索引建议：<code>(create_time)</code> 降序列表默认排序；按需对 <code>notice_title</code> 前缀查询加索引（实现阶段评估数据量）。</p><h3 id="_4-2-字典种子数据" tabindex="-1">4.2 字典种子数据 <a class="header-anchor vp-link" href="#_4-2-字典种子数据" aria-label="Permalink to &quot;4.2 字典种子数据&quot;">​</a></h3><ul><li><strong><code>sys_notice_type</code></strong>：至少两项，例如 <code>1</code> 通知、<code>2</code> 公告（<code>dict_label</code> 中文展示名与需求一致）。</li><li><strong><code>sys_notice_status</code></strong>：至少两项，例如 <code>0</code> 正常、<code>1</code> 关闭。</li></ul><p><code>dict_id</code> / <code>dict_code</code> 须在 Flyway 中选用<strong>与既有迁移及运行库数据不冲突</strong>的固定主键；若仓库尚无其他字典种子，本变更采用独立数值段（例如自 <code>800001</code> 起递增）并在 SQL 注释中标明，避免与后续手工录入冲突。</p><h2 id="_5-接口契约" tabindex="-1">5. 接口契约 <a class="header-anchor vp-link" href="#_5-接口契约" aria-label="Permalink to &quot;5. 接口契约&quot;">​</a></h2><p>统一响应 <code>R</code>；列表分页载荷使用 <code>quickboot-common</code> 已有 <strong><code>PageInfo&lt;T&gt;</code></strong>（含 <code>records</code>、<code>total</code>、<code>current</code>、<code>size</code>、<code>pages</code>），以便前端 <code>C7JsonTable</code> 使用 <code>rows-key=&quot;data.records&quot;</code>、<code>total-key=&quot;data.total&quot;</code>（其中 <code>data</code> 为 <code>R</code> 的业务载荷）。</p><div class="vp-table"><table><thead><tr><th>能力</th><th>方法</th><th>路径</th><th>说明</th></tr></thead><tbody><tr><td>分页列表</td><td>GET</td><td><code>/system/notice/list</code></td><td>Query：<code>pageNum</code>、<code>pageSize</code>、<code>noticeTitle</code>（模糊）、<code>noticeType</code>（精确）、<code>createBy</code>（模糊，对应创建人）；返回 <code>R&lt;PageInfo&lt;SysNoticeVo&gt;&gt;</code></td></tr><tr><td>详情</td><td>GET</td><td><code>/system/notice/{noticeId}</code></td><td>含 <code>noticeContent</code>，供编辑回显</td></tr><tr><td>新增</td><td>POST</td><td><code>/system/notice/create</code></td><td>Body：<code>SysNoticeBo</code>；校验分组 Add</td></tr><tr><td>修改</td><td>POST</td><td><code>/system/notice/update</code></td><td>Body：<code>SysNoticeBo</code>，含 <code>noticeId</code>；分组 Update</td></tr><tr><td>删除</td><td>POST</td><td><code>/system/notice/remove</code></td><td>Body：<code>List&lt;Long&gt;</code>，支持批量</td></tr></tbody></table></div><p><strong>与原始需求文档第 6 节差异</strong>：不以 <code>PUT</code>/<code>DELETE</code> 暴露删除与修改语义，以符合 <code>AGENTS.md</code> 与现有 <code>SysConfigController</code> 风格。</p><h2 id="_6-后端设计" tabindex="-1">6. 后端设计 <a class="header-anchor vp-link" href="#_6-后端设计" aria-label="Permalink to &quot;6. 后端设计&quot;">​</a></h2><h3 id="_6-1-分层与包结构" tabindex="-1">6.1 分层与包结构 <a class="header-anchor vp-link" href="#_6-1-分层与包结构" aria-label="Permalink to &quot;6.1 分层与包结构&quot;">​</a></h3><ul><li>包路径：<code>io.github.genkidoudou.web.system.notice</code>（或项目统一 <code>web.system</code> 下与 <code>config</code>、<code>dept</code> 并列的 <code>notice</code> 子包）。</li><li>分层：<code>controller</code> / <code>service</code> / <code>service.impl</code> / <code>mapper</code> / <code>domain</code> / <code>dto</code>（Bo、QueryBo、Vo）。</li><li>公开类型及 public 成员补充 <strong>JavaDoc</strong>（简体中文为主）。</li></ul><h3 id="_6-2-校验与异常" tabindex="-1">6.2 校验与异常 <a class="header-anchor vp-link" href="#_6-2-校验与异常" aria-label="Permalink to &quot;6.2 校验与异常&quot;">​</a></h3><ul><li>写接口入参 <strong>Jakarta Validation</strong>；标题、类型必填与需求一致。</li><li>业务失败使用项目自定义异常（如 <code>WarningException</code> + 错误码），<strong>禁止</strong>以 <code>IllegalArgumentException</code> 表达业务失败。</li><li>详情/更新时若 <code>noticeId</code> 不存在：明确中文提示。</li><li><code>remove</code> 入参为空列表或含非法 ID：校验拒绝。</li></ul><h3 id="_6-3-富文本消毒与长度" tabindex="-1">6.3 富文本消毒与长度 <a class="header-anchor vp-link" href="#_6-3-富文本消毒与长度" aria-label="Permalink to &quot;6.3 富文本消毒与长度&quot;">​</a></h3><ul><li>在 <strong>Service 层</strong>、持久化前执行 HTML 白名单消毒（推荐 <strong>OWASP Java HTML Sanitizer</strong>；若项目已统一使用其他等价组件则与之对齐）。</li><li>消毒后若内容为空而原始提交非空（例如全部为非法标签），视为业务错误并提示用户。</li><li>消毒后再校验 UTF-8 字符长度不超过 <strong>65535</strong>（与第 2 节澄清一致）。</li></ul><h3 id="_6-4-审计字段" tabindex="-1">6.4 审计字段 <a class="header-anchor vp-link" href="#_6-4-审计字段" aria-label="Permalink to &quot;6.4 审计字段&quot;">​</a></h3><ul><li><code>create_by</code> / <code>update_by</code> / 时间与现有模块一致，从<strong>当前登录用户上下文</strong>写入（实现时对照 <code>dept</code>、<code>config</code> 等已有写法）。</li></ul><h3 id="_6-5-openapi" tabindex="-1">6.5 OpenAPI <a class="header-anchor vp-link" href="#_6-5-openapi" aria-label="Permalink to &quot;6.5 OpenAPI&quot;">​</a></h3><ul><li>Controller 标注 <code>@Tag</code>、<code>@Operation</code>，路径参数与关键 Query 使用 <code>@Parameter</code>。</li></ul><h2 id="_7-前端设计-quick-ui" tabindex="-1">7. 前端设计（quick-ui） <a class="header-anchor vp-link" href="#_7-前端设计-quick-ui" aria-label="Permalink to &quot;7. 前端设计（quick-ui）&quot;">​</a></h2><h3 id="_7-1-页面与组件" tabindex="-1">7.1 页面与组件 <a class="header-anchor vp-link" href="#_7-1-页面与组件" aria-label="Permalink to &quot;7.1 页面与组件&quot;">​</a></h3><ul><li>列表：优先 <strong><code>C7JsonTable</code></strong>，<code>listFunction</code> 调用 <code>GET /system/notice/list</code>，直接兼容 <code>R.data</code> 为 <code>PageInfo</code> 的 <code>records</code>/<code>total</code>。</li><li>查询项：公告标题、公告类型、创建人（界面文案建议使用「创建人」，与澄清结论一致，避免与「操作人员」歧义）。</li><li>表格列：公告编号（<code>noticeId</code>）、公告标题、公告类型、状态、创建人、创建时间；类型/状态使用字典（<code>useDict(&#39;sys_notice_type&#39;,&#39;sys_notice_status&#39;)</code> 或项目等价方式）。</li><li>新增/编辑：弹窗表单；必填标题、类型；状态默认与 RuoYi 参考一致（如 <code>0</code>）；内容区使用富文本编辑器。</li><li>删除：行内删除 + 批量删除，调用 <code>POST /system/notice/remove</code>；成功后 <code>refreshData()</code>。</li></ul><h3 id="_7-2-权限" tabindex="-1">7.2 权限 <a class="header-anchor vp-link" href="#_7-2-权限" aria-label="Permalink to &quot;7.2 权限&quot;">​</a></h3><ul><li>列表查询：<code>system:notice:list</code></li><li>新增：<code>system:notice:add</code></li><li>编辑：<code>system:notice:edit</code></li><li>删除：<code>system:notice:remove</code></li></ul><h3 id="_7-3-视觉与依赖" tabindex="-1">7.3 视觉与依赖 <a class="header-anchor vp-link" href="#_7-3-视觉与依赖" aria-label="Permalink to &quot;7.3 视觉与依赖&quot;">​</a></h3><ul><li>新建/改造页面前遵循仓库根目录 <strong><code>DESIGN.md</code></strong> 与 <code>sdd/前端代码规范.md</code>。</li><li>富文本组件选型以实现阶段依赖为准，须满足设计系统间距与表单布局。</li></ul><h2 id="_8-验收映射" tabindex="-1">8. 验收映射 <a class="header-anchor vp-link" href="#_8-验收映射" aria-label="Permalink to &quot;8. 验收映射&quot;">​</a></h2><div class="vp-table"><table><thead><tr><th>原始验收项</th><th>设计对应</th></tr></thead><tbody><tr><td>新增/编辑后列表及时更新</td><td>提交成功后关闭弹窗并调用表格 <code>refreshData()</code></td></tr><tr><td>类型和状态字典显示正确</td><td>依赖 Flyway 种子 + 前端 <code>dict</code> 拉取与列渲染</td></tr></tbody></table></div><h2 id="_9-测试建议" tabindex="-1">9. 测试建议 <a class="header-anchor vp-link" href="#_9-测试建议" aria-label="Permalink to &quot;9. 测试建议&quot;">​</a></h2><ul><li>Service 单测或集成测：HTML 含 <code>script</code>/事件属性被剔除；超长拒绝；不存在 ID 更新/删除失败提示。</li><li>接口测：分页边界、<code>createBy</code> 与 <code>noticeTitle</code> 组合筛选。</li><li>手动：权限四类账号或 Mock 下按钮显隐。</li></ul><h2 id="_10-后续流程" tabindex="-1">10. 后续流程 <a class="header-anchor vp-link" href="#_10-后续流程" aria-label="Permalink to &quot;10. 后续流程&quot;">​</a></h2><p>实现前阅读：<code>openspec/project.md</code>、<code>sdd/后端代码规范.md</code>、<code>sdd/前端代码规范.md</code>、<code>sdd/数据库设计规范.md</code> 与 <code>DESIGN.md</code>。</p><p>本设计批准后，使用 <strong><code>writing-plans</code></strong> 产出分步实现计划，再进入编码与联调。</p>',48)])])}const p=t(a,[["render",i]]);export{_ as __pageData,p as default};
